// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRubik = makeLoadFont('Rubik');

// Load font at module level to prevent flickering
const { fontFamily: rubikFamily } = loadRubik();



export type UnfoldingNoteProps = Record<string, any>;

// Reusable noise texture for paper realism
const PaperNoise: React.FC = () => (
  <AbsoluteFill style={{ opacity: 0.04, mixBlendMode: "multiply", pointerEvents: "none" }}>
    <svg width="100%" height="100%">
      <filter id="paperNoise">
        <feTurbulence type="fractalNoise" baseFrequency="1.2" numOctaves="3" stitchTiles="stitch" />
      </filter>
      <rect width="100%" height="100%" filter="url(#paperNoise)" />
    </svg>
  </AbsoluteFill>
);

const UnfoldingNote: React.FC<UnfoldingNoteProps> = ({
  backgroundColor = "#d4cec4",
  transparentBackground = false,
  durationInSeconds = 5, // Not directly used in frame math, but required by schema rules
  paperColor = "#f4f0e6",
  textColor = "#f26d5b",
  title = "AMERICA,\nMEET MARY.",
  subtitle = "HOSTED BY MARY CHILDS\nCOMING SOON",
  tapeColor = "rgba(210, 205, 195, 0.8)",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely handle transparent backgrounds
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Paper Dimensions based on Canvas
  const paperWidth = width * 0.75;
  const paperHeight = height * 0.85;
  const panelHeight = paperHeight / 3;

  // Animation Timings & Physics
  // Top panel unfolds first (like opening a letter flap)
  const topUnfoldProgress = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 90 },
  });

  // Bottom panel unfolds second
  const bottomUnfoldProgress = spring({
    frame: frame - 40,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 90 },
  });

  // Entrance animation for the entire note
  const containerEntrance = spring({
    frame,
    fps,
    config: { damping: 12, mass: 1, stiffness: 80 },
  });

  // Calculate Rotations
  // Top panel hinges at the bottom, starts folded down over the middle (-179deg to avoid z-fighting/rendering glitches at exactly 180)
  const topAngle = interpolate(topUnfoldProgress, [0, 1], [-179, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Bottom panel hinges at the top, starts folded up over the middle (179deg)
  const bottomAngle = interpolate(bottomUnfoldProgress, [0, 1], [179, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Container subtle motion
  const containerScale = interpolate(containerEntrance, [0, 1], [0.85, 1]);
  const containerRotate = interpolate(containerEntrance, [0, 1], [-3, 0]);

  // Lighting & Shadows
  // Back faces are slightly darker to simulate being on the outside
  const backFaceOverlayOpacity = 0.05;
  
  // The content component that gets rendered in pieces across the 3 panels.
  // We use `translateY` to shift the content inside each hidden overflow container.
  const FullPaperContent = ({ shiftY }: { shiftY: number }) => (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: paperWidth,
        height: paperHeight,
        transform: `translateY(${shiftY}px)`,
        display: "flex",
        flexDirection: "column",
        padding: "40px",
        boxSizing: "border-box",
        fontFamily: rubikFamily,
        color: textColor,
        textAlign: "center",
      }}
    >
      {/* Top Section (Matches Top Panel) */}
      <div style={{ flex: 1, position: "relative" }}>
        {/* Tape */}
        <div
          style={{
            position: "absolute",
            top: -20,
            left: "50%",
            transform: "translateX(-50%) rotate(-2deg)",
            width: 140,
            height: 45,
            backgroundColor: tapeColor,
            boxShadow: "0 2px 5px rgba(0,0,0,0.05)",
          }}
        />
      </div>

      {/* Middle Section (Matches Middle Panel) */}
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <h1
          style={{
            fontSize: 90,
            fontWeight: 800,
            margin: 0,
            lineHeight: 1.15,
            letterSpacing: "0.08em",
            textTransform: "uppercase",
          }}
        >
          {title.split("\n").map((line, i) => (
            <div key={i}>{line}</div>
          ))}
        </h1>
      </div>

      {/* Bottom Section (Matches Bottom Panel) */}
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", paddingTop: 20 }}>
        <h2
          style={{
            fontSize: 32,
            fontWeight: 600,
            margin: 0,
            lineHeight: 1.5,
            letterSpacing: "0.15em",
            textTransform: "uppercase",
          }}
        >
          {subtitle.split("\n").map((line, i) => (
            <div key={i}>{line}</div>
          ))}
        </h2>
      </div>
    </div>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* 3D Perspective Container */}
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          perspective: "2500px",
        }}
      >
        {/* Wrapper that handles global positioning, scale, and base shadow */}
        <div
          style={{
            position: "relative",
            width: paperWidth,
            height: paperHeight,
            transform: `scale(${containerScale}) rotateZ(${containerRotate}deg)`,
            transformStyle: "preserve-3d",
            boxShadow: "0 30px 60px rgba(0,0,0,0.15)",
          }}
        >
          
          {/* ================= TOP PANEL ================= */}
          <div
            style={{
              position: "absolute",
              top: 0,
              width: "100%",
              height: panelHeight,
              transformOrigin: "bottom center",
              transform: `rotateX(${topAngle}deg)`,
              transformStyle: "preserve-3d",
              zIndex: 3, // Highest z-index so it folds over everything
            }}
          >
            {/* Top Back Face (Visible when completely folded) */}
            <div
              style={{
                position: "absolute",
                width: "100%",
                height: "100%",
                backgroundColor: paperColor,
                transform: "rotateX(180deg)",
                backfaceVisibility: "hidden",
                borderBottom: "1px solid rgba(0,0,0,0.05)",
              }}
            >
              <PaperNoise />
              <div style={{ width: "100%", height: "100%", backgroundColor: `rgba(0,0,0,${backFaceOverlayOpacity})` }} />
            </div>

            {/* Top Front Face */}
            <div
              style={{
                position: "absolute",
                width: "100%",
                height: "100%",
                backgroundColor: paperColor,
                backfaceVisibility: "hidden",
                overflow: "hidden",
              }}
            >
              <PaperNoise />
              <FullPaperContent shiftY={0} />
              {/* Crease shadow at bottom edge */}
              <div style={{ position: "absolute", bottom: 0, width: "100%", height: 20, background: "linear-gradient(to top, rgba(0,0,0,0.06), transparent)" }} />
            </div>
          </div>


          {/* ================= MIDDLE PANEL ================= */}
          {/* Static base panel. Needs lowest z-index so flaps fold over it. */}
          <div
            style={{
              position: "absolute",
              top: panelHeight,
              width: "100%",
              height: panelHeight,
              backgroundColor: paperColor,
              overflow: "hidden",
              zIndex: 1,
            }}
          >
            <PaperNoise />
            <FullPaperContent shiftY={-panelHeight} />
            {/* Crease shadows at top and bottom edges */}
            <div style={{ position: "absolute", top: 0, width: "100%", height: 20, background: "linear-gradient(to bottom, rgba(0,0,0,0.06), transparent)" }} />
            <div style={{ position: "absolute", bottom: 0, width: "100%", height: 20, background: "linear-gradient(to top, rgba(0,0,0,0.06), transparent)" }} />
          </div>


          {/* ================= BOTTOM PANEL ================= */}
          <div
            style={{
              position: "absolute",
              top: panelHeight * 2,
              width: "100%",
              height: panelHeight,
              transformOrigin: "top center",
              transform: `rotateX(${bottomAngle}deg)`,
              transformStyle: "preserve-3d",
              zIndex: 2, // Middle z-index (folds over middle, but under top)
            }}
          >
            {/* Bottom Back Face */}
            <div
              style={{
                position: "absolute",
                width: "100%",
                height: "100%",
                backgroundColor: paperColor,
                transform: "rotateX(-180deg)",
                backfaceVisibility: "hidden",
                borderTop: "1px solid rgba(0,0,0,0.05)",
              }}
            >
              <PaperNoise />
              <div style={{ width: "100%", height: "100%", backgroundColor: `rgba(0,0,0,${backFaceOverlayOpacity})` }} />
            </div>

            {/* Bottom Front Face */}
            <div
              style={{
                position: "absolute",
                width: "100%",
                height: "100%",
                backgroundColor: paperColor,
                backfaceVisibility: "hidden",
                overflow: "hidden",
              }}
            >
              <PaperNoise />
              <FullPaperContent shiftY={-panelHeight * 2} />
              {/* Crease shadow at top edge */}
              <div style={{ position: "absolute", top: 0, width: "100%", height: 20, background: "linear-gradient(to bottom, rgba(0,0,0,0.06), transparent)" }} />
            </div>
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default UnfoldingNote;